function createUser(data: any) {
  if (!data) throw new Error('missing data');
  const name = data.name || 'unknown';
  if (typeof name !== 'string') throw new Error('invalid name');
  return saveToDb({ name });
}

async function fetchProfile(id: string) {
  try {
    const res = await http.get(`/profiles/${id}`);
    return res.data;
  } catch (err) {
    console.error('fetch failed', err);
    return null;
  }
}

// Version A: inline guards
function submitOrderA(order: any) {
  if (!order) throw new Error('order missing');
  if (!order.items || order.items.length === 0) throw new Error('no items');
  if (typeof order.total !== 'number') throw new Error('invalid total');
  return saveOrder(order);
}

// Version B: centralized validator
function submitOrderB(order: any) {
  const result = OrderValidator.validate(order);
  if (!result.ok) throw new Error(result.message);
  return saveOrder(order);
}
